&i2c3 {○1  
 status = "okay"; 
 max96789_1: max96789-1@40 {○2  
  compatible = "maxiam,max96789"; 
  status = "disabled"; 
  reg = <0x40>; 
  reset-gpios = <&pio 134 0>; 
  pinctrl-names = "default"; 
  setting = <&superframe_setting>;○3  
 }; 
}; 

